// frontend/screens/PadMe.jsx
//
// Pad: reach anyone by GLOOBAL ID, on Gloobal's own dial. As symbols go
// in, the ID is looked up; at twelve the person appears and the three
// things you can do with them are one tap each.
//
// Me: the same ID card as Gloobal's profile, so both apps read as one
// account; then the few settings a messenger needs.

import { useState as useStateH13, useEffect as useEffectH13, useRef as useRefH13 } from "react";

function HellooDialScreen({ value, onChange, match, status, onMessage, onCall, onVideo, onScan, mobileMode = false, onToggleMode }) {
  const found = status === "found" && match;
  return <HellooScreen><HellooTop big title="Dial" subtitle="Reach anyone on GLOOBAL · free" right={<><HellooRoundButton Icon={mobileMode ? HlHash : HlMobile} label={mobileMode ? "Dial a GLOOBAL ID" : "Dial a mobile number"} onClick={onToggleMode} /><HellooRoundButton Icon={HlScan} label="Scan a GLOOBAL QR" onClick={onScan} /></>} /><div style={{ flex: 1, minHeight: 0, display: "flex", flexDirection: "column", alignItems: "center", padding: "0 18px", overflow: "hidden" }}><HellooCard style={{ width: "100%", padding: "12px 14px" }}><SymbolChipRow length={12} value={value} masked={false} boxSize={22} fitWidth /></HellooCard><div style={{ width: "100%", minHeight: 74, marginTop: 10 }}>{found ? <HellooCard style={{ display: "flex", alignItems: "center", gap: 12, padding: "11px 14px" }}><HellooAvatar person={match} size={46} online={match.online} /><span style={{ flex: 1, minWidth: 0 }}><span style={{ display: "flex", alignItems: "center", gap: 4, minWidth: 0, maxWidth: "100%" }}><span style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", minWidth: 0, fontSize: 15, fontWeight: 800, color: T.ink }}>{match.handle ? <CreatorHandleText handle={match.handle} /> : match.name}</span>{match && !match.group ? <HellooBadge tier={match.badge || 1} size={12.5} /> : null}</span><span style={{ display: "flex", alignItems: "center", gap: 5, fontSize: 12, color: T.inkSoft, marginTop: 2 }}><FlagEmoji flag={match.flag} size={13} shape="circle" border="none" />{match.city || match.country}{match.online && <span style={{ color: HT.free, fontWeight: 700 }}> · Online</span>}</span></span><span style={{ display: "inline-flex", alignItems: "center", gap: 4, fontSize: 11, fontWeight: 800, color: HT.free, background: HT.freeSoft, borderRadius: 999, padding: "4px 9px" }}><HlCheck size={12} />On Helloo</span></HellooCard> : <div style={{ fontSize: 12.5, color: status === "none" ? T.negative : T.inkFaint, textAlign: "center", padding: "12px 0", fontWeight: 700 }}>{status === "none" ? "Nobody on GLOOBAL has this ID" : status === "looking" ? "Checking…" : value.length ? `${12 - value.length} more` : "Dial the 12 symbols of their GLOOBAL ID"}</div>}</div><div style={{ flex: 1, minHeight: 0, display: "flex", alignItems: "center", justifyContent: "center", width: "100%" }}><SymbolDialPad value={value} onChange={onChange} length={12} soundWhileTyping /></div></div><div style={{ display: "flex", gap: 10, padding: "6px 18px calc(14px + env(safe-area-inset-bottom, 0px))" }}>{[[HlChat, "Message", onMessage, T.accent], [HlPhone, "Call", onCall, HT.free]].map(([Icon, label, fn, color]) => <button key={label} onClick={fn} disabled={!found} aria-label={label} title={label} className="v2-tap" style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", minHeight: 50, borderRadius: 999, border: "none", background: found ? color : T.surfaceSunk, color: found ? "#fff" : T.inkFaint, cursor: found ? "pointer" : "default" }}><Icon size={22} /></button>)}</div></HellooScreen>;
}

// Me (12 Nov rework). What a person asks here, in order: who am I on
// Helloo, what has my attention earned, what can I change, where is help,
// and how do I leave. So: the ID card; what you earned this month, one tap
// from the detail; the settings; a card saying plainly that the photo and
// name are changed in GLOOBAL, and where help is; and Sign out last, apart
// and quiet, asking once more before it signs out.
function HellooMeScreen({ me, stats, onEdit, onQr, onCopy, onRow, onShare, onOpenGloobal, onSignOut, rows: rowsGiven, children, onBack, earned = null, onEarned, onHelp }) {
  const [leaving, setLeaving] = useStateH13(false);
  useEffectH13(() => { if (!leaving) return undefined; const t = setTimeout(() => setLeaving(false), 4000); return () => clearTimeout(t); }, [leaving]);
  const rows = rowsGiven || [[HlRupee, "Who can reach me", "₹2 · ₹2", HT.free], [HlWallet, "Activity", "Time · Earned · Spent", "#0B7A57"], [HlBell, "Notifications", "On", "#EA580C"], [HlShield, "Privacy", "Last seen · everyone", "#2563EB"], [HlPalette, "App theme", (HELLOO_THEMES.find((x) => x.t.bg === T.bg) || HELLOO_THEMES[0]).name, "#9333EA"], [HlBan, "Blocked", "0", "#DC2626"], [HlDrive, "Storage & data", "", "#0E7490"]];
  return <HellooScreen><HellooTop big={!onBack} left={onBack && <NavBackButton onClick={onBack} />} title="Me" right={onEdit && <HellooRoundButton Icon={HlPencil} label="Edit profile" onClick={onEdit} />} /><div style={{ flex: 1, minHeight: 0, overflowY: "auto", padding: "0 16px 90px", display: "flex", flexDirection: "column", gap: 14 }}><div style={{ position: "relative", flexShrink: 0, borderRadius: 26, background: T.gradWallet, padding: "16px 18px", color: "#fff", overflow: "hidden", boxShadow: "0 14px 34px rgba(76,29,149,0.28)" }}><span aria-hidden="true" style={{ position: "absolute", inset: 0, background: "repeating-radial-gradient(circle at 110% -10%, rgba(255,255,255,0.07) 0 1px, transparent 1px 14px)", pointerEvents: "none" }} /><div style={{ position: "relative", display: "flex", alignItems: "center", justifyContent: "space-between", fontSize: 10, fontWeight: 800, letterSpacing: 1.3, textTransform: "uppercase", color: "rgba(255,255,255,0.75)" }}><GloobalWordmark suffix=" ID" /><span>{me.country}</span></div><div style={{ position: "relative", display: "flex", alignItems: "center", gap: 14, marginTop: 14 }}><span style={{ width: 78, height: 78, borderRadius: "50%", flexShrink: 0, border: "3px solid rgba(255,255,255,0.9)", background: "#fff", boxShadow: "0 8px 22px rgba(0,0,0,0.25)" }}><HellooMeAvatar me={me} size={72} /></span><div style={{ flex: 1, minWidth: 0 }}><div style={{ whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", fontSize: 21, fontWeight: 800, fontFamily: T.fontDisplay, letterSpacing: -0.4, lineHeight: 1.15 }}><HellooNameB p={me} label={me.name} /></div><div style={{ fontSize: 12, color: "rgba(255,255,255,0.8)", marginTop: 3 }}>{me.about}</div><style>{"[data-helloo-id] > span > span { flex-wrap: nowrap !important; gap: 1px !important; }"}</style><div data-helloo-id style={{ display: "flex", alignItems: "center", gap: 6, width: "100%", boxSizing: "border-box", marginTop: 9, background: "#fff", borderRadius: 12, padding: "5px 5px 5px 10px", boxShadow: "0 4px 14px rgba(0,0,0,0.12)" }}><span style={{ flex: 1, minWidth: 0, fontSize: "clamp(10.5px, 3.3vw, 14px)", fontWeight: 800, lineHeight: 1.2, whiteSpace: "nowrap", overflow: "hidden", letterSpacing: -0.3 }}><ColoredGloobalId id={me.id} /></span><button onClick={onCopy} aria-label="Copy ID" className="v2-tap" style={{ width: 30, height: 30, flexShrink: 0, borderRadius: 9, border: "none", background: T.accentSoft, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", padding: 0 }}><HlCopy size={15} color={T.accent} /></button></div></div></div><div style={{ position: "relative", display: "flex", gap: 10, marginTop: 14 }}><button onClick={onQr} className="v2-tap" style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", gap: 7, minHeight: 40, borderRadius: 999, border: "1px solid rgba(255,255,255,0.25)", background: "rgba(255,255,255,0.14)", color: "#fff", fontSize: 13, fontWeight: 800, cursor: "pointer", fontFamily: T.fontBody }}><HlQr size={16} />My QR</button><button onClick={onShare} className="v2-tap" style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", gap: 7, minHeight: 40, borderRadius: 999, border: "1px solid rgba(255,255,255,0.25)", background: "rgba(255,255,255,0.14)", color: "#fff", fontSize: 13, fontWeight: 800, cursor: "pointer", fontFamily: T.fontBody }}><HlShare size={16} />Share Helloo</button></div></div>{earned && <button onClick={onEarned} data-testid="helloo-me-earned" className="v2-tap" style={{ flexShrink: 0, display: "flex", alignItems: "center", gap: 12, width: "100%", textAlign: "left", border: "none", borderRadius: HT.radius != null ? HT.radius : 20, padding: "13px 14px", background: HT.freeSoft, cursor: "pointer", fontFamily: T.fontBody }}><span style={{ width: 42, height: 42, borderRadius: 14, background: T.surface, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><HlRupee size={20} color={HT.free} /></span><span style={{ flex: 1, minWidth: 0 }}><span style={{ display: "block", fontSize: 10.5, fontWeight: 800, letterSpacing: 0.8, textTransform: "uppercase", color: HT.free }}>{earned.label || "Your attention earned · this month"}</span><span style={{ display: "block", fontSize: 21, fontWeight: 800, fontFamily: T.fontDisplay, color: T.ink, letterSpacing: -0.4, marginTop: 1 }}>{earned.text}</span><span style={{ display: "block", fontSize: 12, color: T.inkSoft, marginTop: 1 }}>{earned.sub}</span></span><HlChevron size={18} color={HT.free} /></button>}{stats && <HellooCard style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 14px" }}><span style={{ width: 38, height: 38, borderRadius: 12, background: HT.freeSoft, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><HlLock size={18} color={HT.free} /></span><span style={{ fontSize: 13.5, fontWeight: 700, color: T.ink, lineHeight: 1.4 }}>{stats.text || `${stats.feesText || "₹0 in fees"} · ${stats.minutes || 0} free minutes this month`}</span></HellooCard>}<HellooCard>{rows.map(([Icon, title, value, color], i) => <HellooRow key={title} Icon={Icon} color={color} title={title} value={value} first={i === 0} onPress={() => onRow && onRow(title)} />)}</HellooCard>{children}<HellooCard><HellooRow Icon={HlUser} color="#2563EB" title="Change photo or name" value={<span>In <GloobalWordmark /></span>} first onPress={onOpenGloobal} />{onHelp && <HellooRow Icon={HlInfo} color="#0E7490" title="Help & Support" value={<span>In <GloobalWordmark /></span>} onPress={onHelp} />}<HellooRow Icon={HlGlobe} color={T.accent} title={<span>Open <GloobalWordmark /></span>} value="Pay & bank" onPress={onOpenGloobal} /></HellooCard><button onClick={() => (leaving ? onSignOut && onSignOut() : setLeaving(true))} data-testid="helloo-sign-out" className="v2-tap" style={{ alignSelf: "center", display: "inline-flex", alignItems: "center", gap: 7, border: "none", borderRadius: 999, padding: "10px 18px", marginTop: 4, background: leaving ? T.negativeSoft : "transparent", color: leaving ? T.negative : T.inkSoft, fontSize: 13, fontWeight: 800, cursor: "pointer", fontFamily: T.fontBody }}><HlLogOut size={15} />{leaving ? "Tap again to sign out" : "Sign out of Helloo"}</button></div></HellooScreen>;
}

function HellooMyQrScreen({ me, onBack, onSave, onShare }) {
  const qrValue = typeof buildGloobalPayUrl === "function" ? buildGloobalPayUrl(me.id, "person") : null;
  return <HellooScreen><HellooTop left={<NavBackButton onClick={onBack} />} title="My QR" right={<NavFlagBadge flag={me.flag} />} /><div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", padding: "10px 24px" }}><HellooCard style={{ width: "100%", padding: "20px 18px", display: "flex", flexDirection: "column", alignItems: "center", gap: 12 }}><div style={{ display: "flex", alignItems: "center", gap: 10, alignSelf: "stretch" }}><HellooMeAvatar me={me} size={40} /><span style={{ flex: 1, minWidth: 0 }}><span style={{ display: "flex", alignItems: "center", gap: 4, minWidth: 0, maxWidth: "100%" }}><span style={{ minWidth: 0, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", fontSize: 15, fontWeight: 800, color: T.ink }}>{me.name}</span>{me && !me.group ? <HellooBadge tier={me.badge || 1} size={12.5} /> : null}</span><span style={{ display: "block", fontSize: 11.5, color: T.inkSoft }}>Scan to message or call me on Helloo</span></span><HellooMark size={34} /></div><div style={{ width: 220, height: 220, borderRadius: 18, background: "#fff", padding: 10, boxSizing: "border-box" }}>{qrValue ? <GloobalQrSvg value={qrValue} /> : null}</div><div style={{ fontSize: 15, fontWeight: 800 }}><ColoredGloobalId id={me.id} /></div></HellooCard><div style={{ display: "flex", gap: 10, width: "100%", marginTop: 16 }}><HellooSecondary Icon={HlDownload} onClick={() => onSave && onSave(qrValue)}>Save</HellooSecondary><HellooPrimary Icon={HlShare} onClick={() => onShare && onShare(qrValue)}>Share</HellooPrimary></div><div style={{ fontSize: 11.5, color: T.inkFaint, textAlign: "center", marginTop: 14, lineHeight: 1.45 }}>The same code as your GLOOBAL QR: scanned in Helloo it opens a chat, scanned in GLOOBAL it opens a payment.</div></div></HellooScreen>;
}

// The shop behind a business, on its profile: the store mark lives here
// (not on its name in chats), with the few facts worth a glance — what kind
// of shop, where, whether it is open, how much is on its list — and the
// way into the menu. `shop` is null while it loads and for a person.
function HellooShopCard({ person, shop, onMenu }) {
  if (!person || !person.handle) return null;
  const line = (label, value) => (value ? <div style={{ display: "flex", justifyContent: "space-between", gap: 12, padding: "8px 0", borderTop: `1px solid ${T.line}`, fontSize: 13 }}><span style={{ color: T.inkSoft, fontWeight: 600, flexShrink: 0 }}>{label}</span><span style={{ color: T.ink, fontWeight: 700, textAlign: "right", minWidth: 0, overflowWrap: "anywhere" }}>{value}</span></div> : null);
  return <HellooSection title="Shop"><HellooCard style={{ padding: "12px 14px" }}><div data-testid="helloo-shop-card"><div style={{ display: "flex", alignItems: "center", gap: 10, paddingBottom: 10 }}><span style={{ width: 38, height: 38, borderRadius: 12, background: T.accentSoft, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><HlStore size={19} color={T.accent} /></span><span style={{ minWidth: 0 }}><span style={{ display: "block", fontSize: 15, fontWeight: 800, color: T.ink }}><HellooNameB p={person} label={<CreatorHandleText handle={person.handle} icon={false} />} /></span><span style={{ display: "block", fontSize: 12, color: T.inkSoft, marginTop: 1 }}>{shop ? (shop.kind || "On GLOOBAL") : "Loading the shop…"}</span></span></div>{shop ? <>{line("Where", shop.where)}{line("Now", shop.open)}{line("On its list", shop.count)}{line("Rated", shop.rating)}</> : null}{person.calls && person.calls.mode !== "always" ? line("Calls", person.calls.mode === "off" ? "Not taken · message instead" : `${person.calls.from}–${person.calls.to}`) : null}{onMenu ? <div style={{ marginTop: 10 }}><HellooSecondary onClick={onMenu} Icon={HlStore}>See the menu</HellooSecondary></div> : null}</div></HellooCard></HellooSection>;
}

function HellooContactScreen({ media = null, mediaFilter = "all", onMediaFilter, shop = null, onMenu, person, onBack, onMessage, onCall, onVideo, onPay, onGroup, groups = null, status = "", together = null, currency = "INR", onSaveReview, shops = null, onShop, reach = null, reachBusy = false, onReach }) {
  const action = (Icon, label, fn, color) => <button onClick={fn} disabled={!fn} className="v2-tap" style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 6, border: "none", background: "none", padding: 0, cursor: fn ? "pointer" : "default", fontFamily: T.fontBody, opacity: fn ? 1 : 0.4 }}><span style={{ width: 54, height: 54, borderRadius: "50%", background: color, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: `0 10px 22px -10px ${color}` }}><Icon size={23} color="#fff" /></span><span style={{ fontSize: 11.5, fontWeight: 800, color: T.ink }}>{label}</span></button>;
  const money = (v, c) => typeof fmtMoney === "function" ? hellooMoneyText(v, c || currency) : `${v} ${c || currency}`;
  const mins = (sec) => { const m = Math.round((sec || 0) / 60); return m >= 60 ? `${Math.floor(m / 60)}h ${String(m % 60).padStart(2, "0")}m` : `${m} min`; };
  const stat = (big, small, color) => <span style={{ flex: 1, minWidth: 0, background: T.surfaceAlt, borderRadius: 14, padding: "10px 8px", textAlign: "center" }}><span style={{ display: "block", fontSize: String(big).length > 11 ? 13 : String(big).length > 8 ? 15 : 17, fontWeight: 800, fontFamily: T.fontDisplay, color: color || T.ink, letterSpacing: -0.3, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{big}</span><span style={{ display: "block", fontSize: 10.5, fontWeight: 700, color: T.inkSoft, marginTop: 2, whiteSpace: "nowrap" }}>{small}</span></span>;
  const t = together;
  // A shop's profile carries Call and Pay only (you are already in its
  // chat, and a shop is not video-called). Call is grey, with the hours,
  // when the shop is not taking calls.
  const biz = hellooIsBusiness(person);
  const callsShut = Boolean(biz && person.calls && !person.calls.open);
  if (!biz) return <HellooFriendProfile media={media} mediaFilter={mediaFilter} onMediaFilter={onMediaFilter} person={person} status={status} onBack={onBack} onMessage={onMessage} onCall={onCall} onVideo={onVideo} onPay={onPay} together={together} groups={groups} shops={shops} onShop={onShop} reach={reach} reachBusy={reachBusy} onReach={onReach} />;
  if (biz) return <HellooShopProfile shop={shop} person={person} onBack={onBack} onMessage={onMessage} onCall={onCall} onPay={onPay} onMenu={onMenu} together={together} groups={groups} onSaveReview={onSaveReview} />;
  return <HellooScreen><HellooTop left={<NavBackButton onClick={onBack} />} title="" right={null} /><div style={{ flex: 1, minHeight: 0, overflowY: "auto", padding: "0 16px 30px", display: "flex", flexDirection: "column", gap: 14 }}><div style={{ display: "flex", flexDirection: "column", alignItems: "center", textAlign: "center" }}><HellooAvatar person={person} size={92} online={person.online} /><div style={{ marginTop: 12 }}><HellooVerifiedName person={person} size={22} /></div><div style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12.5, color: T.inkSoft, marginTop: 4 }}><FlagEmoji flag={person.flag} size={15} shape="circle" border="1px solid rgba(0,0,0,0.14)" />{person.city ? `${person.city}, ` : ""}{person.country}{person.online ? <span style={{ color: HT.free, fontWeight: 700 }}> · Online</span> : status ? <span> · {status}</span> : null}</div><div style={{ fontSize: 14, fontWeight: 800, marginTop: 8 }}><ColoredGloobalId id={person.id} /></div>{person.about && <div style={{ fontSize: 12.5, color: T.inkSoft, marginTop: 6 }}>{person.about}</div>}</div><div style={{ display: "flex", gap: 8, padding: "4px 6px 2px" }}>{biz ? <>{action(HlPhone, callsShut ? (person.calls.mode === "off" ? "Calls off" : `Calls ${person.calls.from}–${person.calls.to}`) : "Call", callsShut ? undefined : onCall, callsShut ? T.inkFaint : HT.free)}{action(HlRupee, "Pay", onPay, "#0B7A57")}</> : <>{action(HlChat, "Message", onMessage, T.accent)}{action(HlPhone, "Call", onCall, HT.free)}{action(HlVideo, "Video", onVideo, "#DB2777")}{action(HlRupee, "Pay", onPay, "#0B7A57")}</>}</div><HellooShopCard person={person} shop={shop} onMenu={onMenu} /><HellooSection title="Together" hint={t && t.since ? `since ${hellooWhen(t.since)}` : ""}><HellooCard style={{ padding: "12px 12px" }}>{t ? <><div style={{ display: "flex", gap: 8 }}>{stat(mins(t.calls.seconds), "on calls together", HT.free)}{stat(String(t.calls.connected), t.calls.connected === 1 ? "call connected" : "calls connected")}{stat(String(t.messages.fromMe + t.messages.fromThem), "messages")}</div><div style={{ display: "flex", gap: 8, marginTop: 8 }}>{stat(t.money.toThem.n ? money(t.money.toThem.amount, t.money.toThem.currency) : "—", `you paid ${hellooName(person).split(" ")[0]}`, "#0B7A57")}{stat(t.money.toMe.n ? money(t.money.toMe.amount, t.money.toMe.currency) : "—", `${hellooName(person).split(" ")[0]} paid you`, "#0B7A57")}</div><div style={{ display: "flex", justifyContent: "space-between", fontSize: 11.5, color: T.inkFaint, marginTop: 10, padding: "0 2px" }}><span>{t.messages.fromMe} from you · {t.messages.fromThem} from them</span><span>{t.calls.video ? `${t.calls.video} video` : ""}{t.calls.video && t.calls.missed ? " · " : ""}{t.calls.missed ? `${t.calls.missed} not answered` : ""}</span></div></> : <div style={{ fontSize: 12.5, color: T.inkFaint, textAlign: "center", padding: "6px 0" }}>Loading…</div>}</HellooCard></HellooSection>{groups && groups.map((rows, g) => <HellooCard key={g}>{rows.map(([Icon, title, value, onPress, danger, color, toggle], k) => (typeof toggle === "boolean" ? <HellooToggleRow key={typeof title === "string" ? title : k} Icon={Icon} color={color} title={title} note={value} on={toggle} onChange={onPress} danger={danger} first={k === 0} testid={`helloo-profile-toggle-${String(title).toLowerCase().replace(/[^a-z]+/g, "-")}`} /> : <HellooRow key={typeof title === "string" ? title : k} Icon={Icon} color={color} title={title} value={value} onPress={onPress} danger={danger} first={k === 0} />))}</HellooCard>)}</div></HellooScreen>;
}

// A shop's profile. A purple cover carries its name, what kind of shop it
// is and its GLOOBAL ID, with the logo over the cover's edge (the store
// badge on the logo is the one store mark on the page). Then Call and Pay
// (Pay in the shop's own money, as CEL | $), one Menu / Services row —
// a tea stall's menu and a bank's offers are the same list — the shop's
// feedback, and the call time you have spent together.
var HELLOO_COVER = "linear-gradient(135deg,#4F46E5,#7C3AED 55%,#C026D3)";
function hellooCelSign(code) {
  const c = code || "USD";
  return (typeof CURRENCY_SYMBOL === "object" && CURRENCY_SYMBOL[c]) || c;
}
function hellooCelAmount(amount) {
  return Number(amount || 0).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
function HellooCel({ amount, currency, size = 15 }) {
  return <span style={{ display: "inline-flex", alignItems: "baseline", gap: 5, whiteSpace: "nowrap" }}><span style={{ fontSize: size, fontWeight: 800, fontFamily: T.fontDisplay, color: T.ink }}>{hellooCelAmount(amount)}</span><span style={{ fontSize: 10, fontWeight: 800, color: T.inkSoft }}>CEL | {hellooCelSign(currency)}</span></span>;
}
function HellooStars({ n = 0, size = 12, onPick }) {
  return <span style={{ display: "inline-flex", gap: onPick ? 8 : 3 }}>{[1, 2, 3, 4, 5].map((i) => onPick
    ? <button key={i} aria-label={`${i} star${i === 1 ? "" : "s"}`} aria-pressed={i <= n} onClick={() => onPick(i)} className="v2-tap" style={{ border: "none", background: "none", padding: 0, cursor: "pointer", fontSize: size, lineHeight: 1, color: i <= n ? "#F59E0B" : "#D6D3E8" }}>★</button>
    : <span key={i} aria-hidden="true" style={{ fontSize: size, lineHeight: 1, color: i <= Math.round(n) ? "#F59E0B" : "#D6D3E8" }}>★</span>)}</span>;
}
function HellooShopProfile({ shop, person, onBack, onMessage, onCall, onPay, onMenu, together, groups, onSaveReview }) {
  const [sheet, setSheet] = useStateH13(null);
  const [draft, setDraft] = useStateH13({ stars: 0, text: "", busy: false, error: "" });
  const t = together;
  const who = person.handle || hellooName(person);
  const code = (typeof COUNTRY_CURRENCY === "object" && COUNTRY_CURRENCY[person.iso]) || "USD";
  const rv = shop && shop.reviews ? shop.reviews : null;
  const sum = rv && rv.summary ? rv.summary : { count: 0, average: 0, byStars: {} };
  const list = rv && Array.isArray(rv.reviews) ? rv.reviews : [];
  const shut = Boolean(person.calls && !person.calls.open);
  const callLabel = shut ? (person.calls.mode === "off" ? "Calls off" : `Calls ${person.calls.from}–${person.calls.to}`) : "Call";
  const openText = shop && shop.open ? shop.open : "";
  const isOpen = /^open/i.test(openText);
  const mins = (sec) => { const m = Math.round((sec || 0) / 60); return m >= 60 ? `${Math.floor(m / 60)}h ${String(m % 60).padStart(2, "0")}m` : `${m} min`; };
  const head = (txt, right) => <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", margin: "0 2px 8px" }}><span style={{ fontSize: 12, fontWeight: 800, letterSpacing: 1, color: T.inkSoft }}>{txt}</span>{right}</div>;
  const pill = (Icon, txt, fn, bg, fg, sub) => <button onClick={fn} disabled={!fn} className="v2-tap" style={{ flex: 1, minWidth: 0, height: 52, borderRadius: 16, border: "none", background: bg, color: fg, display: "flex", alignItems: "center", justifyContent: "center", gap: 7, fontFamily: T.fontBody, fontSize: 15, fontWeight: 800, cursor: fn ? "pointer" : "default", whiteSpace: "nowrap" }}>{Icon ? <Icon size={19} color={fg} /> : null}<span>{txt}</span>{sub ? <span style={{ fontSize: 11, fontWeight: 800, padding: "2px 6px", borderRadius: 7, background: "rgba(255,255,255,0.22)" }}>{sub}</span> : null}</button>;
  const startFeedback = () => { const m = rv && rv.mine; setDraft({ stars: m ? m.stars : 0, text: m ? m.text : "", busy: false, error: "" }); setSheet("feedback"); };
  const save = () => {
    if (!draft.stars || draft.busy || !onSaveReview) return;
    setDraft((d) => Object.assign({}, d, { busy: true, error: "" }));
    Promise.resolve(onSaveReview(draft.stars, draft.text.trim()))
      .then(() => setSheet(null))
      .catch((err) => setDraft((d) => Object.assign({}, d, { busy: false, error: (err && err.message) || "Couldn't save. Try again." })));
  };
  const reviewRow = (r, first) => <div key={r.id} style={{ padding: "11px 0", borderTop: first ? "none" : `1px solid ${T.line}` }}><div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}><span style={{ fontSize: 13, fontWeight: 800, color: T.ink }}>{r.mine ? "You" : "A customer"}</span><span style={{ fontSize: 11.5, color: T.inkFaint }}>{r.at ? hellooWhen(r.at) : ""}</span></div><div style={{ marginTop: 3 }}><HellooStars n={r.stars} /></div>{r.text ? <div style={{ fontSize: 12.5, color: T.inkSoft, marginTop: 4, lineHeight: 1.4, overflowWrap: "anywhere" }}>{r.text}</div> : null}</div>;
  const canAsk = !(rv && rv.isOwner);
  // ── THE SHOP, IN ITS OWN COLOUR ────────────────────────────────────
  // The top is the main colour of the shop's own logo, light above and
  // deeper below, ending in a soft curve: no blur, no picture to crop,
  // and every shop gets a colour of its own with nothing to set. Pay wears
  // the same colour. A shop with no logo wears its theme's shop colour.
  const pic = useHellooPictureColour(person.photo);
  const sc = hellooShopColors();
  const base = pic || hellooHexRgb(sc.accent) || [11, 122, 85];
  const deep = (k) => hellooRgb(base, k);
  const items = (shop && Array.isArray(shop.items)) ? shop.items : [];
  // The money the shop works in: what its own items are priced in, and
  // only when it has none, its country's. Pay and the prices then always
  // show the same sign — an Indian shop reads CEL | ₹ on both.
  const shopCode = ((items.find((it) => it.currency) || {}).currency) || code;
  const chip = (txt, on) => <span key={typeof txt === "string" ? txt : "c"} style={{ display: "inline-flex", alignItems: "center", gap: 5, fontSize: 12, fontWeight: 800, color: on ? "#B7F7D4" : "#fff", background: "rgba(255,255,255,0.18)", borderRadius: 999, padding: "5px 11px", whiteSpace: "nowrap" }}>{txt}</span>;
  const iconBtn = (Icon, label, fn, off) => <button key={label} onClick={fn} disabled={!fn || off} aria-label={label} className="v2-tap" style={{ width: 64, border: "none", background: "none", display: "flex", flexDirection: "column", alignItems: "center", gap: 4, cursor: fn && !off ? "pointer" : "default", fontFamily: T.fontBody, padding: 0, flexShrink: 0, opacity: off ? 0.45 : 1 }}><Icon size={22} color={deep(0.85)} /><span style={{ fontSize: 11.5, fontWeight: 800, color: T.ink, whiteSpace: "nowrap" }}>{label}</span></button>;
  const itemRow = (it, i) => <button key={it.id || i} onClick={onMenu} disabled={!onMenu} className="v2-tap" style={{ width: "100%", display: "flex", alignItems: "center", gap: 12, padding: "10px 12px", border: "none", borderTop: i ? `1px solid ${T.line}` : "none", background: "none", cursor: onMenu ? "pointer" : "default", textAlign: "left", fontFamily: T.fontBody }}><span style={{ width: 54, height: 54, borderRadius: 14, overflow: "hidden", background: hellooRgb(base, 1, 0.14), display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>{it.photo ? <img src={it.photo} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : <HlStore size={22} color={deep(0.85)} />}</span><span style={{ flex: 1, minWidth: 0 }}><span style={{ display: "block", fontSize: 14.5, fontWeight: 800, color: T.ink, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{it.title}</span>{it.priceText ? <span style={{ display: "block", fontSize: 13, fontWeight: 800, color: deep(0.8), marginTop: 2 }}>{it.priceText}</span> : null}</span><span style={{ width: 34, height: 34, borderRadius: "50%", background: hellooRgb(base, 1, 0.14), display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><HlPlus size={17} color={deep(0.85)} /></span></button>;
  const sec = (txt, right) => <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", margin: "0 2px 10px" }}><span style={{ fontSize: 17, fontWeight: 800, fontFamily: T.fontDisplay, color: T.ink }}>{txt}</span>{right}</div>;
  const link = (txt, fn) => <button onClick={fn} style={{ border: "none", background: "none", padding: 0, cursor: "pointer", color: deep(0.85), fontWeight: 800, fontSize: 13, fontFamily: T.fontBody }}>{txt}</button>;
  return <HellooScreen><div style={{ position: "relative", flex: 1, minHeight: 0, display: "flex", flexDirection: "column" }}><div data-testid="helloo-shop-card" style={{ flex: 1, minHeight: 0, overflowY: "auto", display: "block", background: T.bg, paddingBottom: 110 }}>
    <div data-testid="helloo-shop-top" style={{ position: "relative", padding: "calc(74px + env(safe-area-inset-top, 0px)) 18px 24px", background: `linear-gradient(165deg, ${deep(1.18)} 0%, ${deep(0.92)} 55%, ${deep(0.62)} 100%)`, borderRadius: "0 0 34px 34px", overflow: "hidden", transition: "background 0.4s ease" }}>
      <div aria-hidden="true" style={{ position: "absolute", right: -60, top: -40, width: 220, height: 220, borderRadius: "50%", background: "rgba(255,255,255,0.10)" }} /><div aria-hidden="true" style={{ position: "absolute", left: -50, bottom: -90, width: 200, height: 200, borderRadius: "50%", background: "rgba(255,255,255,0.07)" }} />
      <div style={{ position: "absolute", left: 14, right: 14, top: "calc(14px + env(safe-area-inset-top, 0px))", display: "flex", justifyContent: "space-between", alignItems: "center" }}><button onClick={onBack} aria-label="Back" className="v2-tap" style={{ width: 42, height: 42, borderRadius: "50%", border: "none", background: "rgba(255,255,255,0.22)", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}><HlBack size={19} color="#fff" /></button>{person.flag ? <span title={person.country || ""} style={{ width: 42, height: 42, borderRadius: "50%", background: "#fff", display: "flex", alignItems: "center", justifyContent: "center" }}><FlagEmoji flag={person.flag} size={26} shape="circle" border="none" /></span> : null}</div>
      <div style={{ position: "relative", display: "flex", gap: 14, alignItems: "center" }}><span style={{ width: 84, height: 84, borderRadius: 24, border: "3px solid #fff", overflow: "hidden", flexShrink: 0, background: "rgba(255,255,255,0.25)", boxShadow: "0 14px 28px -12px rgba(0,0,0,0.45)", display: "flex", alignItems: "center", justifyContent: "center", color: "#fff", fontSize: 30, fontWeight: 800, fontFamily: T.fontDisplay }}>{person.photo ? <img src={person.photo} alt="" style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : hellooInitials(who)}</span><span style={{ minWidth: 0 }}><span style={{ display: "flex", alignItems: "center", gap: 6, minWidth: 0 }}><span style={{ fontSize: 25, fontWeight: 800, fontFamily: T.fontDisplay, letterSpacing: -0.4, color: "#fff", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{who}</span><HellooBadge tier={(person && person.badge) || 1} size={24} /></span>{(shop && (shop.kind || shop.where)) ? <span style={{ display: "block", fontSize: 13.5, color: "rgba(255,255,255,0.88)", marginTop: 3, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{[shop.kind, shop.where].filter(Boolean).join(" · ")}</span> : null}<span style={{ display: "block", fontSize: 11.5, color: "rgba(255,255,255,0.72)", marginTop: 4, letterSpacing: 1.2 }}>{person.id}</span></span></div>
      <div style={{ position: "relative", display: "flex", gap: 6, marginTop: 14, flexWrap: "wrap" }}>{openText ? chip(<><span style={{ width: 7, height: 7, borderRadius: "50%", background: isOpen ? "#6EE7B7" : "rgba(255,255,255,0.6)" }} />{openText}</>, isOpen) : null}{sum.count ? chip(`★ ${Number(sum.average).toFixed(1)} · ${sum.count}`) : null}{t && t.calls && t.calls.seconds ? chip(`${mins(t.calls.seconds)} together`) : null}</div>
    </div>
    {items.length || onMenu ? <div style={{ padding: "22px 16px 0" }}>{sec("Menu / Services", onMenu ? link(items.length > 5 ? `All ${items.length} ›` : "Open ›", onMenu) : null)}{items.length ? <HellooCard style={{ padding: 0, overflow: "hidden" }}>{items.slice(0, 5).map(itemRow)}</HellooCard> : <HellooCard style={{ padding: "14px 16px", fontSize: 13, color: T.inkSoft }}>{shop && shop.count ? shop.count : "What this shop offers"}</HellooCard>}</div> : null}
    <div style={{ padding: "22px 16px 0" }}>{sec("Feedback", sum.count ? link(`All ${sum.count} ›`, () => setSheet("reviews")) : null)}<HellooCard style={{ padding: "14px 16px" }}>
      {!rv ? <div style={{ fontSize: 12.5, color: T.inkFaint, textAlign: "center", padding: "6px 0" }}>Loading…</div> : <>
        {sum.count ? <div style={{ display: "flex", alignItems: "center", gap: 12 }}><span style={{ fontSize: 30, fontWeight: 800, fontFamily: T.fontDisplay, color: T.ink, lineHeight: 1 }}>{Number(sum.average).toFixed(1)}</span><span><HellooStars n={sum.average} size={13} /><span style={{ display: "block", fontSize: 11.5, color: T.inkSoft, marginTop: 3 }}>{sum.count} {sum.count === 1 ? "review" : "reviews"}</span></span></div> : <div style={{ fontSize: 13.5, color: T.inkSoft, textAlign: "center", padding: "2px 0 4px" }}>No feedback yet.</div>}
        {list[0] ? <div style={{ borderTop: `1px solid ${T.line}`, marginTop: 12 }}>{reviewRow(list[0], true)}</div> : null}
        {canAsk ? <button onClick={startFeedback} data-testid="helloo-give-feedback" className="v2-tap" style={{ width: "100%", height: 44, marginTop: 8, borderRadius: 14, border: `1px solid ${T.line}`, background: T.surface, fontFamily: T.fontBody, fontSize: 13.5, fontWeight: 800, color: deep(0.85), display: "flex", alignItems: "center", justifyContent: "center", gap: 6, cursor: "pointer" }}><HlStar size={16} color={deep(0.85)} />{rv.mine ? "Change your feedback" : "Give feedback"}</button> : null}
      </>}
    </HellooCard></div>
    {groups && groups.length ? <div style={{ padding: "22px 16px 0", display: "flex", flexDirection: "column", gap: 12 }}>{groups.map((rows, g) => <HellooCard key={g}>{rows.map(([Icon, title, value, onPress, danger, color, toggle], k) => (typeof toggle === "boolean" ? <HellooToggleRow key={typeof title === "string" ? title : k} Icon={Icon} color={color} title={title} note={value} on={toggle} onChange={onPress} danger={danger} first={k === 0} testid={`helloo-profile-toggle-${String(title).toLowerCase().replace(/[^a-z]+/g, "-")}`} /> : <HellooRow key={typeof title === "string" ? title : k} Icon={Icon} color={color} title={title} value={value} onPress={onPress} danger={danger} first={k === 0} />))}</HellooCard>)}</div> : null}
  </div>
  {/* Message, Call and Pay, held at the bottom where the thumb is. No
      video: a shop is not video-called. */}
  <div data-testid="helloo-shop-bar" style={{ position: "absolute", left: 0, right: 0, bottom: 0, padding: "10px 12px calc(12px + env(safe-area-inset-bottom, 0px))", background: T.surface, boxShadow: "0 -10px 30px -18px rgba(0,0,0,0.35)", borderRadius: "22px 22px 0 0", display: "flex", gap: 4, alignItems: "center" }}>{iconBtn(HlChat, "Message", onMessage || onBack)}{iconBtn(HlPhone, shut ? callLabel : "Call", shut ? undefined : onCall, shut)}<button onClick={onPay} disabled={!onPay} data-testid="helloo-shop-pay" aria-label={`Pay ${who}`} className="v2-tap" style={{ flex: 1, minWidth: 0, height: 52, borderRadius: 999, border: "none", background: `linear-gradient(135deg, ${deep(0.95)}, ${deep(0.7)})`, color: "#fff", fontFamily: T.fontBody, fontSize: 16, fontWeight: 800, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", gap: 9, boxShadow: `0 14px 26px -12px ${hellooRgb(base, 0.6, 0.7)}` }}><span style={{ fontSize: 18, fontWeight: 800, letterSpacing: 0.4, whiteSpace: "nowrap" }}>CEL | {hellooCelSign(shopCode)}</span></button></div>
  {sheet === "reviews" && <HellooSheet label="Feedback" onClose={() => setSheet(null)}><div style={{ fontSize: 16, fontWeight: 800, fontFamily: T.fontDisplay, color: T.ink }}>Feedback for {who}</div><div style={{ fontSize: 12, color: T.inkSoft, marginTop: 3 }}>From people who have paid this shop. Names are never shown.</div><div style={{ marginTop: 8 }}>{list.map((r, i) => reviewRow(r, i === 0))}</div></HellooSheet>}
  {sheet === "feedback" && <HellooSheet label="Give feedback" onClose={() => setSheet(null)}><div style={{ fontSize: 16, fontWeight: 800, fontFamily: T.fontDisplay, color: T.ink }}>How was {who}?</div>
    {rv && !rv.canReview ? <><div style={{ fontSize: 13, color: T.inkSoft, marginTop: 8, lineHeight: 1.5 }}>Feedback comes from people who have paid this shop. Pay once, then you can rate it.</div>{onPay ? <div style={{ marginTop: 14 }}><HellooPrimary onClick={() => { setSheet(null); onPay(); }}>Pay {who}</HellooPrimary></div> : null}</>
      : <><div style={{ fontSize: 12.5, color: T.inkSoft, marginTop: 4 }}>Your name is never shown with it.</div><div style={{ display: "flex", justifyContent: "center", margin: "16px 0 12px" }}><HellooStars n={draft.stars} size={34} onPick={(n) => setDraft((d) => Object.assign({}, d, { stars: n, error: "" }))} /></div><textarea data-testid="helloo-feedback-text" value={draft.text} maxLength={280} onChange={(e) => setDraft((d) => Object.assign({}, d, { text: e.target.value }))} placeholder="Say what was good, or what could be better (optional)" rows={3} style={{ width: "100%", boxSizing: "border-box", borderRadius: 14, border: `1px solid ${T.line}`, padding: "10px 12px", fontFamily: T.fontBody, fontSize: 14, color: T.ink, resize: "none", background: T.surface }} /><div style={{ fontSize: 11, color: T.inkFaint, textAlign: "right", marginTop: 3 }}>{draft.text.length}/280</div>{draft.error ? <div style={{ fontSize: 12.5, color: "#DC2626", marginTop: 6 }}>{draft.error}</div> : null}<div style={{ marginTop: 10 }}><HellooPrimary disabled={!draft.stars || draft.busy} onClick={save}>{draft.busy ? "Saving…" : "Send feedback"}</HellooPrimary></div></>}
  </HellooSheet>}
  </div></HellooScreen>;
}

// Who can reach me, just for one person: Free, Pays per message (the
// usual price, or one of their own — tap the price to change it), or
// Never. The same choice sits on their profile and in your chat with
// them. `reach` is { reachMode, reachPrice, reachCurrency } or null while
// it loads.
function HellooReachChoice({ who, reach, busy = false, onChange }) {
  const mode = reach ? reach.reachMode : "";
  const saved = reach ? Number(reach.reachPrice) || 0 : 0;
  const [open, setOpen] = useStateH13(false);
  const [draft, setDraft] = useStateH13(null);
  const timer = useRefH13(null);
  const sign = hellooCelSign(reach && reach.reachCurrency);
  const price = draft !== null ? draft : saved;
  const fmt = (n) => (Number(n) || 0).toFixed(2);
  const tag = (n) => <span style={{ display: "inline-flex", alignItems: "baseline", gap: 4, padding: "3px 8px", borderRadius: 8, background: "#0B7A571A", color: "#0B7A57", fontWeight: 800 }}><span style={{ fontSize: 13 }}>{fmt(n)}</span><span style={{ fontSize: 10 }}>CEL | {sign}</span></span>;
  // Sliding saves once the thumb rests for a moment, not on every tenth.
  const slide = (v) => {
    const n = Math.max(0.1, hellooReachTenths(v));
    setDraft(n);
    clearTimeout(timer.current);
    timer.current = setTimeout(() => { onChange && onChange("pay", n); setDraft(null); }, 600);
  };
  const rows = [
    ["free", HlChat, "Free", `${who} messages you free`, HT.free],
    ["pay", HlWallet, "Pays per message", price ? `${who} pays each message · tap to change the price` : `${who} pays your price · tap to set one`, "#0B7A57"],
    ["never", HlBan, "Never", `${who} can't message you`, "#DC2626"]
  ];
  const radio = (on) => <span aria-hidden="true" style={{ width: 22, height: 22, borderRadius: "50%", border: on ? "none" : `2px solid ${T.line}`, background: on ? T.accent : "transparent", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>{on && <HlCheck size={13} color="#fff" strokeWidth={3} />}</span>;
  const pct = ((Math.max(0.1, price || 0.1) - 0.1) / (HELLOO_REACH_MAX - 0.1)) * 100;
  return <HellooCard><div role="radiogroup" aria-label={`Who can reach me: ${who}`} data-testid="helloo-reach-person">{rows.map(([k, Icon, label, sub, c], i) => <div key={k} style={{ borderTop: i ? `1px solid ${T.line}` : "none", background: mode === k ? c + "0D" : "none" }}><button role="radio" aria-checked={mode === k} data-testid={`helloo-reach-${k}`} disabled={!reach || busy} onClick={() => { if (k === "pay" && mode === "pay") { setOpen((v) => !v); return; } setOpen(k === "pay"); onChange && onChange(k); }} className="v2-tap" style={{ width: "100%", display: "flex", alignItems: "center", gap: 12, padding: "12px 14px", border: "none", background: "none", textAlign: "left", fontFamily: T.fontBody, cursor: reach && !busy ? "pointer" : "default", opacity: reach ? 1 : 0.5 }}><span style={{ width: 38, height: 38, borderRadius: 12, background: c + "1A", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><Icon size={18} color={c} /></span><span style={{ flex: 1, minWidth: 0 }}><span style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 14.5, fontWeight: 800, color: T.ink, flexWrap: "wrap" }}>{label}{k === "pay" && price ? tag(price) : null}</span><span style={{ display: "block", fontSize: 12, color: T.inkSoft, marginTop: 2 }}>{sub}</span></span>{radio(mode === k)}</button>
    {k === "pay" && mode === "pay" && open ? <div data-testid="helloo-reach-slider" style={{ padding: "0 16px 14px 64px" }}><div style={{ position: "relative", height: 40 }}><div style={{ position: "absolute", left: 0, right: 0, top: 17, height: 6, borderRadius: 3, background: T.line }} /><div style={{ position: "absolute", left: 0, width: `${pct}%`, top: 17, height: 6, borderRadius: 3, background: `linear-gradient(90deg, ${HT.free}, #0B7A57)` }} /><input type="range" min={0.1} max={HELLOO_REACH_MAX} step={HELLOO_REACH_STEP} value={Math.max(0.1, price || 0.1)} disabled={busy} onChange={(e) => slide(e.target.value)} aria-label={`What ${who} pays per message, in CEL ${sign}`} style={{ position: "absolute", inset: 0, width: "100%", opacity: 0, cursor: "pointer", margin: 0 }} /><span aria-hidden="true" style={{ position: "absolute", left: `calc(${pct}% - 13px)`, top: 7, width: 26, height: 26, borderRadius: "50%", background: "#fff", border: "3px solid #0B7A57", boxShadow: T.shadowCard, pointerEvents: "none" }} /></div><div style={{ display: "flex", justifyContent: "space-between", fontSize: 10.5, fontWeight: 700, color: T.inkFaint }}><span>0.10 CEL | {sign}</span><span>{fmt(HELLOO_REACH_MAX)} CEL | {sign}</span></div></div> : null}</div>)}</div></HellooCard>;
}

// A person's profile: a purple cover with their picture, name and GLOOBAL
// ID, their country's flag once in the top corner; Message, Call, Video and
// Pay in a card over the cover's edge; who can reach you, just for them;
// the shops they chose to show; and the call time you have spent together.
function HellooFriendProfile({ media = null, mediaFilter = "all", onMediaFilter, person, status, onBack, onMessage, onCall, onVideo, onPay, together, groups, shops, onShop, reach, reachBusy, onReach }) {
  const t = together;
  const first = hellooName(person).split(" ")[0];
  const code = (typeof COUNTRY_CURRENCY === "object" && COUNTRY_CURRENCY[person.iso]) || "INR";
  const mins = (sec) => { const m = Math.round((sec || 0) / 60); return m >= 60 ? `${Math.floor(m / 60)}h ${String(m % 60).padStart(2, "0")}m` : `${m} min`; };
  const head = (txt, right) => <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", margin: "0 2px 8px" }}><span style={{ fontSize: 12, fontWeight: 800, letterSpacing: 1, color: T.inkSoft }}>{txt}</span>{right}</div>;
  const btn = (Icon, label, fn, c) => <button key={label} onClick={fn} disabled={!fn} className="v2-tap" style={{ flex: 1, minWidth: 0, height: 60, borderRadius: 16, border: "none", background: c + "14", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 4, fontFamily: T.fontBody, cursor: fn ? "pointer" : "default", opacity: fn ? 1 : 0.45 }}><Icon size={20} color={c} /><span style={{ fontSize: 11.5, fontWeight: 800, color: T.ink }}>{label}</span></button>;
  const shopCard = ({ person: sp, shop }) => <button key={sp.accountId} onClick={() => onShop && onShop(sp)} className="v2-tap" style={{ flex: "0 0 210px", borderRadius: 18, background: T.surface, border: `1px solid ${T.line}`, padding: 12, display: "flex", gap: 10, alignItems: "center", textAlign: "left", fontFamily: T.fontBody, cursor: "pointer" }}><span style={{ position: "relative", width: 46, height: 46, flexShrink: 0 }}>{sp.photo ? <img src={sp.photo} alt="" style={{ width: 46, height: 46, borderRadius: 14, objectFit: "cover", display: "block" }} /> : <span style={{ width: 46, height: 46, borderRadius: 14, background: T.accentSoft, color: T.accent, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 16, fontWeight: 800, fontFamily: T.fontDisplay }}>{hellooInitials(sp.handle || sp.name)}</span>}<span style={{ position: "absolute", right: -4, bottom: -4, width: 19, height: 19, borderRadius: 7, background: T.accent, border: `2px solid ${T.surface}`, display: "flex", alignItems: "center", justifyContent: "center" }}><HlStore size={10} color="#fff" /></span></span><span style={{ minWidth: 0 }}><span style={{ display: "flex", alignItems: "center", gap: 4, minWidth: 0, maxWidth: "100%" }}><span style={{ minWidth: 0, fontSize: 13.5, fontWeight: 800, color: T.ink, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{sp.handle || sp.name}</span>{sp && !sp.group ? <HellooBadge tier={sp.badge || 1} size={12.5} /> : null}</span><span style={{ display: "block", fontSize: 11.5, color: T.inkSoft, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{[shop && shop.kind, shop && shop.reviews && shop.reviews.summary && shop.reviews.summary.count ? `★ ${Number(shop.reviews.summary.average).toFixed(1)}` : ""].filter(Boolean).join(" · ") || "Shop on GLOOBAL"}</span>{shop && shop.open ? <span style={{ display: "block", fontSize: 11, fontWeight: 700, color: /^open/i.test(shop.open) ? HT.free : T.inkFaint, marginTop: 1, whiteSpace: "nowrap" }}>{shop.open}</span> : null}</span></button>;
  return <HellooScreen><div data-testid="helloo-person-profile" style={{ flex: 1, minHeight: 0, overflowY: "auto", display: "flex", flexDirection: "column" }}>
    <div style={{ position: "relative", height: 236, flexShrink: 0, background: HELLOO_COVER, display: "flex", flexDirection: "column", alignItems: "center", paddingTop: 10, boxSizing: "border-box" }}>
      <div style={{ position: "absolute", inset: 0, opacity: 0.16, backgroundImage: "radial-gradient(circle at 85% 20%, #fff 0, transparent 40%), radial-gradient(circle at 10% 90%, #fff 0, transparent 35%)" }} />
      <div style={{ alignSelf: "stretch", padding: "0 12px", display: "flex", justifyContent: "space-between", alignItems: "center", position: "relative" }}><button onClick={onBack} aria-label="Back" className="v2-tap" style={{ width: 40, height: 40, borderRadius: "50%", border: "none", background: "rgba(255,255,255,0.22)", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}><HlBack size={20} color="#fff" /></button>{person.flag ? <span title={person.country} style={{ width: 34, height: 34, borderRadius: "50%", background: "rgba(255,255,255,0.95)", display: "flex", alignItems: "center", justifyContent: "center" }}><FlagEmoji flag={person.flag} size={24} shape="circle" border="1px solid rgba(0,0,0,0.12)" /></span> : null}</div>
      <div style={{ marginTop: -14, borderRadius: "50%", background: T.bg, lineHeight: 0, position: "relative" }}><HellooAvatar person={person} size={84} flag={false} online={person.online} /></div>
      <div style={{ marginTop: 8, display: "flex", alignItems: "center", gap: 6, maxWidth: "88%", position: "relative" }}><span style={{ fontSize: 23, fontWeight: 800, fontFamily: T.fontDisplay, color: "#fff", letterSpacing: -0.4, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{hellooName(person)}</span><HellooBadge tier={(person && person.badge) || 1} size={22} /></div>
      <div style={{ marginTop: 6, display: "flex", alignItems: "center", gap: 8, position: "relative" }}><span style={{ padding: "4px 9px", borderRadius: 9, background: "rgba(255,255,255,0.95)", fontSize: 12, fontWeight: 800 }}><ColoredGloobalId id={person.id} /></span>{person.online ? <span style={{ fontSize: 12, fontWeight: 800, color: "#BBF7D0" }}>● Online</span> : status ? <span style={{ fontSize: 12, fontWeight: 700, color: "rgba(255,255,255,0.8)" }}>{status}</span> : null}</div>
    </div>
    <div style={{ margin: "-24px 16px 0", position: "relative", background: T.surface, borderRadius: 22, padding: 8, boxShadow: "0 14px 30px -16px rgba(30,27,75,0.35)", display: "flex", gap: 6 }}>{btn(HlChat, "Message", onMessage, T.accent)}{btn(HlPhone, "Call", onCall, HT.free)}{btn(HlVideo, "Video", onVideo, "#DB2777")}{btn(HlWallet, "Pay", onPay, "#0B7A57")}</div>
    <div style={{ padding: "16px 16px 30px", display: "flex", flexDirection: "column", gap: 16 }}>
      {onReach ? <div>{head("WHO CAN REACH ME", <span style={{ fontSize: 12, color: T.inkSoft }}>just for {first}</span>)}<HellooReachChoice who={first} reach={reach} busy={reachBusy} onChange={onReach} /></div> : null}
      {shops && shops.length ? <div>{head(`${first.toUpperCase()}'S SHOPS`, <span style={{ fontSize: 12, color: T.inkSoft }}>{shops.length}</span>)}<div style={{ display: "flex", gap: 10, overflowX: "auto", paddingBottom: 2 }}>{shops.map(shopCard)}</div></div> : null}
      {t ? <div>{head("TOGETHER", t.since ? <span style={{ fontSize: 12.5, color: T.inkSoft }}>since {hellooWhen(t.since)}</span> : null)}<HellooCard style={{ padding: 14 }}><div style={{ display: "flex", alignItems: "center", gap: 12, padding: "2px 2px 12px" }}><span style={{ width: 44, height: 44, borderRadius: 14, background: HT.free + "1A", display: "flex", alignItems: "center", justifyContent: "center" }}><HlPhone size={20} color={HT.free} /></span><span><span style={{ display: "block", fontSize: 22, fontWeight: 800, fontFamily: T.fontDisplay, color: T.ink, lineHeight: 1.1 }}>{mins(t.calls.seconds)}</span><span style={{ display: "block", fontSize: 12, color: T.inkSoft, fontWeight: 700 }}>on calls together</span></span></div><div style={{ borderRadius: 14, background: T.surfaceAlt, padding: "2px 12px" }}>{[[`You paid ${first}`, t.money.toThem], [`${first} paid you`, t.money.toMe]].map(([k, m], i) => <div key={i} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, padding: "10px 0", borderTop: i ? `1px solid ${T.line}` : "none" }}><span style={{ fontSize: 13, fontWeight: 700, color: T.inkSoft }}>{k}</span>{m.n ? <HellooCel amount={m.amount} currency={m.currency} /> : <b style={{ color: T.inkFaint }}>—</b>}</div>)}</div></HellooCard></div> : null}
      {media ? <HellooProfileMedia state={media} filter={mediaFilter} onFilter={onMediaFilter} /> : null}
      {groups && groups.map((rows, g) => <HellooCard key={g}>{rows.map(([Icon, title, value, onPress, danger, color, toggle], k) => (typeof toggle === "boolean" ? <HellooToggleRow key={typeof title === "string" ? title : k} Icon={Icon} color={color} title={title} note={value} on={toggle} onChange={onPress} danger={danger} first={k === 0} testid={`helloo-profile-toggle-${String(title).toLowerCase().replace(/[^a-z]+/g, "-")}`} /> : <HellooRow key={typeof title === "string" ? title : k} Icon={Icon} color={color} title={title} value={value} onPress={onPress} danger={danger} first={k === 0} />))}</HellooCard>)}
    </div>
  </div></HellooScreen>;
}

// Privacy → what stands for you where your photo would be: the photo,
// nothing (your initials), or one emoji. Shops keep their own logo.
var HELLOO_PICTURE_EMOJI = ["😀", "😎", "🙂", "🤓", "🥳", "😇", "🦊", "🐼", "🐯", "🦁", "🐵", "🦉", "🌸", "🌻", "🌙", "⭐", "🔥", "🌈", "⚽", "🎧", "🎨", "📚", "🚀", "❤️"];
function HellooPictureChoice({ picture, me, disabled = false, onChange }) {
  return <HellooPrivacyPanel picture={picture} me={me} disabled={disabled} onPicture={onChange} />;
}

// Privacy, as one screen you can read at a glance: at the top, you as
// others see you (your picture, your name, "Online" or nothing); under it
// the three pictures to choose from, drawn as themselves; then the one
// switch. Every change shows in the preview at once.
function HellooPrivacyPanel({ picture, me, disabled = false, onPicture, online = null, onOnline }) {
  const mode = (picture && picture.mode) || "photo";
  const emoji = (picture && picture.emoji) || "";
  const showOnline = online !== false;
  const as = (m) => ({ id: me && (me.gloobalId || me.id), name: me && me.name, photo: m === "photo" ? me && me.photo : null, emoji: m === "emoji" ? (emoji || HELLOO_PICTURE_EMOJI[0]) : null });
  const tile = (key, label) => { const on = mode === key; return <button key={key} role="radio" aria-checked={on} data-testid={`helloo-picture-${key}`} disabled={disabled} onClick={() => { if (key === "emoji") onPicture({ mode: "emoji", emoji: emoji || HELLOO_PICTURE_EMOJI[0] }); else onPicture({ mode: key, emoji: "" }); }} className="v2-tap" style={{ flex: 1, minWidth: 0, display: "flex", flexDirection: "column", alignItems: "center", gap: 8, padding: "14px 6px 12px", borderRadius: 18, border: on ? `2px solid ${T.accent}` : `1px solid ${T.line}`, background: on ? T.accentSoft : T.surface, cursor: "pointer", fontFamily: T.fontBody, position: "relative" }}><HellooAvatar person={as(key)} size={48} flag={false} /><span style={{ fontSize: 13, fontWeight: 800, color: on ? T.accent : T.ink }}>{label}</span>{on && <span aria-hidden="true" style={{ position: "absolute", top: 8, right: 8, width: 18, height: 18, borderRadius: "50%", background: T.accent, display: "flex", alignItems: "center", justifyContent: "center" }}><HlCheck size={11} color="#fff" strokeWidth={3} /></span>}</button>; };
  const sec = (t) => <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: 1, color: T.inkFaint, margin: "18px 4px 8px", textTransform: "uppercase" }}>{t}</div>;
  return <div data-testid="helloo-privacy-panel">
    {/* You, as people see you */}
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", padding: "6px 0 4px" }}><span style={{ position: "relative", display: "inline-flex" }}><HellooAvatar person={as(mode)} size={84} flag={false} />{onOnline && showOnline ? <span aria-hidden="true" style={{ position: "absolute", right: 4, bottom: 4, width: 18, height: 18, borderRadius: "50%", background: HT.free, border: `3px solid ${T.bg}` }} /> : null}</span><span style={{ fontSize: 18, fontWeight: 800, fontFamily: T.fontDisplay, color: T.ink, marginTop: 10, maxWidth: "100%", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}><HellooNameB p={me || {}} label={(me && me.name) || "You"} /></span>{onOnline ? <span style={{ fontSize: 12.5, fontWeight: 700, color: showOnline ? HT.free : T.inkFaint, marginTop: 2 }}>{showOnline ? "Online" : "No online or last seen"}</span> : null}<span style={{ fontSize: 11.5, color: T.inkFaint, marginTop: 6 }}>How people see you in chats and calls</span></div>
    {sec("Picture")}
    <div role="radiogroup" aria-label="My picture" style={{ display: "flex", gap: 8 }}>{tile("photo", "Photo")}{tile("hidden", "Initials")}{tile("emoji", "Emoji")}</div>
    {mode === "emoji" && <HellooCard style={{ marginTop: 10, padding: 8 }}><div data-testid="helloo-picture-emojis" style={{ display: "grid", gridTemplateColumns: "repeat(8, 1fr)", gap: 2 }}>{HELLOO_PICTURE_EMOJI.map((e) => <button key={e} aria-label={`Use ${e}`} aria-pressed={emoji === e} disabled={disabled} onClick={() => onPicture({ mode: "emoji", emoji: e })} className="v2-tap" style={{ height: 40, borderRadius: 12, border: "none", background: emoji === e ? T.accentSoft : "transparent", boxShadow: emoji === e ? `inset 0 0 0 2px ${T.accent}` : "none", fontSize: 22, lineHeight: 1, cursor: "pointer", padding: 0 }}>{e}</button>)}</div></HellooCard>}
    {onOnline ? <>{sec("Online")}<HellooCard style={{ padding: "12px 14px" }}><div style={{ display: "flex", alignItems: "center", gap: 12 }}><span style={{ width: 38, height: 38, borderRadius: 12, background: HT.free + "1A", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>{showOnline ? <HlEye size={18} color={HT.free} /> : <HlEyeOff size={18} color={T.inkSoft} />}</span><span style={{ flex: 1, minWidth: 0 }}><span style={{ display: "block", fontSize: 14.5, fontWeight: 800, color: T.ink }}>Online and last seen</span><span style={{ display: "block", fontSize: 12, color: T.inkSoft, marginTop: 1 }}>{showOnline ? "Shown to people you chat with" : "Hidden from everyone"}</span></span><button role="switch" aria-checked={showOnline} aria-label="Show when I'm online" data-testid="helloo-privacy-online" disabled={online === null} onClick={() => onOnline(!showOnline)} className="v2-tap" style={{ width: 48, height: 28, borderRadius: 14, border: "none", background: showOnline ? HT.free : T.line, position: "relative", cursor: "pointer", padding: 0, flexShrink: 0 }}><span style={{ position: "absolute", top: 3, left: showOnline ? 23 : 3, width: 22, height: 22, borderRadius: "50%", background: "#fff", boxShadow: "0 1px 3px rgba(0,0,0,0.25)", transition: "left 0.18s" }} /></button></div></HellooCard></> : null}
    <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 6, fontSize: 11.5, color: T.inkFaint, margin: "14px 4px 0" }}><HlLock size={12} color={T.inkFaint} />Your phone number is never shown</div>
  </div>;
}

// "Use Helloo as": yourself, or a shop your GLOOBAL ID runs. Each has
// its own chats and calls; `fresh` is how many chats have something new.
function HellooFaceSheet({ faces = [], current = "", onPick, onClose }) {
  const shops = faces.filter((f) => f.kind === "shop").length;
  return <HellooSheet title="Use Helloo as" onClose={onClose}><div style={{ fontSize: 12.5, color: T.inkSoft, lineHeight: 1.5, margin: "0 2px 12px" }}>Your GLOOBAL ID runs {shops === 1 ? "a shop" : `${shops} shops`}. Each one has its own chats and calls here, apart from your personal ones. People who reach a shop see the shop's name, not yours.</div><HellooCard>{faces.map((f, i) => { const on = f.as === current; const shop = f.kind === "shop"; return <button key={f.as} data-testid={`helloo-face-${shop ? f.handle : "self"}`} aria-pressed={on} onClick={() => onPick && onPick(f)} className="v2-tap" style={{ width: "100%", display: "flex", alignItems: "center", gap: 12, padding: "12px 14px", border: "none", borderTop: i ? `1px solid ${T.line}` : "none", background: "none", cursor: "pointer", textAlign: "left", fontFamily: T.fontBody }}><span style={{ width: 40, height: 40, borderRadius: shop ? 13 : "50%", background: shop ? T.accentSoft : T.surfaceAlt, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>{shop ? <HlStore size={19} color={T.accent} /> : <HlUser size={19} color={T.inkSoft} />}</span><span style={{ flex: 1, minWidth: 0 }}><span style={{ display: "flex", alignItems: "center", gap: 4, minWidth: 0, maxWidth: "100%" }}><span style={{ minWidth: 0, fontSize: 14.5, fontWeight: 800, color: T.ink, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{shop ? <CreatorHandleText handle={f.handle} icon={false} /> : f.name}</span>{f && !f.group ? <HellooBadge tier={f.badge || 1} size={12.5} /> : null}</span><span style={{ display: "block", fontSize: 12, color: T.inkSoft, marginTop: 1 }}>{shop ? "Shop" : "Personal"}{f.fresh > 0 && !on ? <span style={{ color: T.accent, fontWeight: 800 }}> · {f.fresh} new</span> : null}</span></span><span aria-hidden="true" style={{ width: 22, height: 22, borderRadius: "50%", border: on ? "none" : `2px solid ${T.line}`, background: on ? T.accent : "transparent", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>{on && <HlCheck size={13} color="#fff" strokeWidth={3} />}</span></button>; })}</HellooCard></HellooSheet>;
}

// Tapping your picture at the top: who you message as, in a card in the
// middle — your own face and each shop's logo side by side. Tap a face to
// open its profile (Me); tap the message icon under it to message as it.
// The one you are now has a ring and a tick.
function HellooFaceCard({ faces = [], current = "", photos = {}, onPick, onProfile, onClose }) {
  useHellooBackLayer(true, onClose);
  const many = faces.length > 3;
  const faceOf = (f) => {
    const shop = f.kind === "shop";
    const photo = shop ? (photos["logo:" + f.accountId] || "") : (photos[f.accountId] || "");
    return { id: f.accountId, name: shop ? (f.handle || f.name) : f.name, short: shop ? "" : String(f.name || "").split(" ")[0], photo };
  };
  return <div data-testid="helloo-face-card-layer" onClick={onClose} style={{ position: "fixed", inset: 0, zIndex: 80, background: "rgba(15,23,42,0.42)", backdropFilter: "blur(6px)", WebkitBackdropFilter: "blur(6px)", display: "flex", alignItems: "center", justifyContent: "center", padding: 16, boxSizing: "border-box", fontFamily: T.fontBody }}>
    <div role="dialog" aria-modal="true" aria-label="Message as" data-testid="helloo-face-card" onClick={(e) => e.stopPropagation()} style={{ position: "relative", width: "100%", maxWidth: 380, maxHeight: "100%", overflowY: "auto", boxSizing: "border-box", borderRadius: 28, background: HT.cardBg || T.surface, boxShadow: "0 24px 60px rgba(15,23,42,0.28)", padding: "22px 14px 14px" }}>
      <button type="button" onClick={onClose} aria-label="Close" className="v2-tap" style={{ position: "absolute", right: 10, top: 10, width: 36, height: 36, border: "none", background: "none", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}><HlX size={20} color={T.inkFaint} /></button>
      <div style={{ display: "flex", justifyContent: "center" }}><HellooWordmark size={20} /></div>
      <div style={{ textAlign: "center", fontSize: 17, fontWeight: 900, color: T.ink, marginTop: 8, fontFamily: T.fontDisplay }}>Message as</div>
      <div style={{ textAlign: "center", fontSize: 12.5, color: T.inkSoft, marginTop: 3, lineHeight: 1.45, padding: "0 12px" }}>Each one has its own chats and calls.</div>
      <div data-testid="helloo-face-card-row" style={{ display: "grid", gridTemplateColumns: `repeat(${many ? 3 : Math.max(1, faces.length)}, minmax(0, 1fr))`, gap: "16px 6px", marginTop: 18 }}>
        {faces.map((f) => {
          const on = f.as === current; const shop = f.kind === "shop"; const who = faceOf(f);
          return <div key={f.as} style={{ minWidth: 0, display: "flex", flexDirection: "column", alignItems: "center", gap: 4 }}>
            <button type="button" data-testid={`helloo-face-profile-${shop ? f.handle : "self"}`} aria-label={`${who.name}${shop ? " (shop)" : ""}: profile`} onClick={() => onProfile && onProfile(f)} className="v2-tap" style={{ minWidth: 0, maxWidth: "100%", display: "flex", flexDirection: "column", alignItems: "center", gap: 6, border: "none", background: "none", padding: "2px 2px 0", cursor: "pointer", fontFamily: T.fontBody }}>
            <span style={{ position: "relative", padding: 3, borderRadius: "50%", background: on ? `conic-gradient(${T.accent}, #2563EB, #DB2777, ${T.accent})` : "transparent", display: "flex" }}>
              <span style={{ borderRadius: "50%", padding: 2, background: HT.cardBg || T.surface, display: "flex" }}>
                {shop && !who.photo
                  ? <span style={{ width: 62, height: 62, borderRadius: "50%", background: T.accentSoft, display: "flex", alignItems: "center", justifyContent: "center" }}><HlStore size={28} color={T.accent} /></span>
                  : <HellooAvatar person={who} size={62} flag={false} />}
              </span>
              {on ? <span aria-hidden="true" style={{ position: "absolute", right: 0, bottom: 0, width: 22, height: 22, borderRadius: "50%", background: T.accent, border: `2px solid ${HT.cardBg || T.surface}`, display: "flex", alignItems: "center", justifyContent: "center" }}><HlCheck size={12} color="#fff" strokeWidth={3} /></span>
                : shop && who.photo ? <span aria-hidden="true" style={{ position: "absolute", right: 0, bottom: 0, width: 22, height: 22, borderRadius: "50%", background: T.accentSoft, border: `2px solid ${HT.cardBg || T.surface}`, display: "flex", alignItems: "center", justifyContent: "center" }}><HlStore size={12} color={T.accent} /></span> : null}
            </span>
            <span style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 3, maxWidth: "100%", minWidth: 0 }}><span style={{ minWidth: 0, fontSize: 13, fontWeight: 800, color: T.ink, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{shop ? <CreatorHandleText handle={f.handle} icon={false} /> : (who.short || who.name)}</span><HellooBadge tier={f.badge || 1} size={11.5} /></span>
            <span style={{ fontSize: 11, fontWeight: 700, color: T.inkFaint, marginTop: -4, whiteSpace: "nowrap" }}>{shop ? "Shop" : "Personal"}{f.fresh > 0 && !on ? <span style={{ color: "#DB2777", fontWeight: 900 }}> · {f.fresh} new</span> : null}</span>
            </button>
            <button type="button" data-testid={`helloo-face-${shop ? f.handle : "self"}`} aria-pressed={on} aria-label={`Message as ${who.name}${shop ? " (shop)" : ""}`} onClick={() => onPick && onPick(f)} className="v2-tap" style={{ width: 44, height: 40, display: "flex", alignItems: "center", justifyContent: "center", border: "none", background: "none", padding: 0, cursor: "pointer" }}>
              <span style={{ display: "flex" }}><HlChat size={26} color={on ? T.accent : "#0E7490"} fill={on ? T.accent : "#0E7490"} strokeWidth={1.6} /></span>
            </button>
          </div>;
        })}
      </div>
      <div style={{ textAlign: "center", fontSize: 11.5, color: T.inkFaint, marginTop: 12 }}>Tap a picture for its profile</div>
    </div>
  </div>;
}

// When the shop takes calls: always, between two times, or not at all.
function HellooShopCallsSheet({ calls, shopName = "", onSave, onClose }) {
  const [mode, setMode] = useStateH13((calls && calls.mode) || "always");
  const [from, setFrom] = useStateH13((calls && calls.from) || "10:00");
  const [to, setTo] = useStateH13((calls && calls.to) || "18:00");
  const [busy, setBusy] = useStateH13(false);
  const pick = (key, title, sub) => <button key={key} role="radio" aria-checked={mode === key} data-testid={`helloo-calls-${key}`} onClick={() => setMode(key)} className="v2-tap" style={{ width: "100%", display: "flex", alignItems: "center", gap: 12, padding: "12px 14px", border: "none", borderTop: key === "always" ? "none" : `1px solid ${T.line}`, background: "none", cursor: "pointer", textAlign: "left", fontFamily: T.fontBody }}><span style={{ flex: 1, minWidth: 0 }}><span style={{ display: "block", fontSize: 14.5, fontWeight: 800, color: T.ink }}>{title}</span><span style={{ display: "block", fontSize: 12, color: T.inkSoft, marginTop: 1 }}>{sub}</span></span><span aria-hidden="true" style={{ width: 22, height: 22, borderRadius: "50%", border: mode === key ? "none" : `2px solid ${T.line}`, background: mode === key ? T.accent : "transparent", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>{mode === key && <HlCheck size={13} color="#fff" strokeWidth={3} />}</span></button>;
  const time = (label, value, set, id) => <label style={{ flex: 1, display: "flex", flexDirection: "column", gap: 5, fontSize: 11.5, fontWeight: 800, color: T.inkSoft }}>{label}<input type="time" data-testid={id} value={value} onChange={(e) => set(e.target.value)} style={{ border: `1px solid ${T.line}`, borderRadius: 14, background: T.surface, padding: "11px 12px", fontSize: 15, fontWeight: 700, color: T.ink, fontFamily: T.fontBody, outline: "none" }} /></label>;
  const bad = mode === "hours" && (!from || !to || from === to);
  return <HellooSheet title="Shop calls" onClose={onClose}><div style={{ fontSize: 12.5, color: T.inkSoft, lineHeight: 1.5, margin: "0 2px 12px" }}>When people can call {shopName || "your shop"} on Helloo. Messages always reach you.</div><HellooCard><div role="radiogroup" aria-label="When the shop takes calls">{pick("always", "Always", "Anyone you allow can call at any time")}{pick("hours", "Set hours", "Calls only between two times, every day")}{pick("off", "Off", "No calls · people message the shop instead")}</div></HellooCard>{mode === "hours" && <div style={{ display: "flex", gap: 10, marginTop: 12 }}>{time("From", from, setFrom, "helloo-calls-from")}{time("To", to, setTo, "helloo-calls-to")}</div>}<div style={{ marginTop: 14 }}><HellooPrimary disabled={busy || bad} onClick={async () => { setBusy(true); try { await (onSave && onSave({ mode, from, to })); } finally { setBusy(false); } }}>Save</HellooPrimary></div></HellooSheet>;
}

function HellooNewGroupSheet({ people, picked = [], name = "", onClose }) {
  return <HellooSheet title="New group" onClose={onClose}><div style={{ display: "flex", alignItems: "center", gap: 12 }}><button aria-label="Group photo" className="v2-tap" style={{ width: 52, height: 52, borderRadius: "50%", border: `2px dashed ${T.line}`, background: T.surface, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}><HlCamera size={20} color={T.inkFaint} /></button><input value={name} readOnly placeholder="Group name" style={{ flex: 1, border: `1px solid ${T.line}`, borderRadius: 14, background: T.surface, padding: "12px 14px", fontSize: 14.5, color: T.ink, fontFamily: T.fontBody, outline: "none" }} /></div><div style={{ fontSize: 10.5, fontWeight: 800, letterSpacing: 0.8, textTransform: "uppercase", color: T.inkFaint, margin: "18px 2px 8px" }}>Add people · {picked.length} picked</div><HellooCard>{people.map((p, i) => { const on = picked.includes(p.id); return <div key={p.id} style={{ display: "flex", alignItems: "center", gap: 12, padding: "10px 14px", borderTop: i ? `1px solid ${T.line}` : "none" }}><HellooAvatar person={p} size={40} /><span style={{ flex: 1, minWidth: 0, fontSize: 14, fontWeight: 800, color: T.ink }}><HellooNameB p={p} /></span><span aria-hidden="true" style={{ width: 22, height: 22, borderRadius: "50%", border: on ? "none" : `2px solid ${T.line}`, background: on ? T.accent : "transparent", display: "flex", alignItems: "center", justifyContent: "center" }}>{on && <HlCheck size={13} color="#fff" strokeWidth={3} />}</span></div>; })}</HellooCard><div style={{ marginTop: 14 }}><HellooPrimary disabled={!name || picked.length === 0} Icon={HlUsers}>Create group</HellooPrimary></div></HellooSheet>;
}

// ── CONTACTS ──────────────────────────────────────────────────────────
//
// Everyone you have on Helloo: people you paid or were paid by on GLOOBAL
// and people you have chatted with. The search box filters as you type,
// by name and by GLOOBAL ID. Helloo never reads the phone's address book.
// A saved name is yours alone (the chat's saved name): shown here first,
// with their own GLOOBAL name under it, and listed under "Saved".
function HellooContactsScreen({ me, contacts: given = [], saved = {}, onSaveName, onSaveToggle, query = "", onQuery, onOpen, onAdd, onBack, autoFocus = false, onMessage, onCall, onVideo, onRemove }) {
  // A saved contact shows under the name you gave it (this chat's name, or
  // the one saved with the contact on any of your sides).
  const contacts = given.map((p) => { const mine = saved[p.accountId] || p.savedName || ""; return mine ? Object.assign({}, p, { name: mine, accountName: p.name, saved: true }) : p; });
  const savedN = contacts.filter((p) => p.saved).length;
  // The list is just faces and names. A tap opens the row: country, their
  // GLOOBAL ID, and Message · Call · Video. Tap the name again, or
  // another row, to close it.
  const [openRow, setOpenRow] = useStateH13(null);
  // People and shops apart: a shop you paid once does not sit among friends.
  const [kind, setKind] = useStateH13("people");
  const peopleN = contacts.filter((p) => !p.handle).length;
  const shopsN = contacts.length - peopleN;
  const q = query.trim().toLowerCase();
  const ofKind = kind === "saved" ? contacts.filter((p) => p.saved) : shopsN && peopleN ? contacts.filter((p) => (kind === "shops" ? Boolean(p.handle) : !p.handle)) : contacts;
  const cardOf = openRow ? contacts.find((x) => x.id === openRow) || null : null;
  const shown = q ? ofKind.filter((p) => (p.name || "").toLowerCase().includes(q) || (p.accountName || "").toLowerCase().includes(q) || (p.gloobalId || "").includes(query.trim()) || (p.handle || "").toLowerCase().includes(q)) : ofKind;
  return <HellooScreen><HellooTop left={<NavBackButton onClick={onBack} />} title="Contacts" subtitle={`${peopleN} ${peopleN === 1 ? "person" : "people"}${shopsN ? ` · ${shopsN} ${shopsN === 1 ? "shop" : "shops"}` : ""} · by GLOOBAL ID only`} right={<HellooRoundButton Icon={HlPlus} label="Add someone" onClick={onAdd} solid />} /><div style={{ padding: "0 16px 10px", flexShrink: 0 }}><label style={{ display: "flex", alignItems: "center", gap: 8, background: T.surface, border: `1px solid ${T.line}`, borderRadius: 999, padding: "10px 14px" }}><HlSearch size={17} color={T.inkFaint} /><input autoFocus={autoFocus} value={query} onChange={(e) => onQuery && onQuery(e.target.value)} placeholder="Search by name or GLOOBAL ID" style={{ flex: 1, minWidth: 0, border: "none", outline: "none", background: "none", fontSize: 14, color: T.ink, fontFamily: T.fontBody }} />{query && <button onClick={() => onQuery && onQuery("")} aria-label="Clear" style={{ border: "none", background: "none", padding: 0, cursor: "pointer", display: "flex" }}><HlX size={16} color={T.inkFaint} /></button>}</label>{(shopsN && peopleN) || savedN ? <div role="tablist" style={{ display: "flex", gap: 6, marginTop: 10 }}><span role="tab" aria-selected={kind === "people"}><HellooChip on={kind === "people"} count={peopleN} onClick={() => { setKind("people"); setOpenRow(null); }}>People</HellooChip></span>{shopsN ? <span role="tab" aria-selected={kind === "shops"}><HellooChip on={kind === "shops"} count={shopsN} onClick={() => { setKind("shops"); setOpenRow(null); }}>Shops</HellooChip></span> : null}<span role="tab" aria-selected={kind === "saved"} data-testid="helloo-contacts-saved"><HellooChip on={kind === "saved"} count={savedN} onClick={() => { setKind("saved"); setOpenRow(null); }}>Saved</HellooChip></span></div> : null}</div><div style={{ flex: 1, minHeight: 0, overflowY: "auto", padding: "0 16px 30px" }}>{shown.length === 0 ? <HellooCard style={{ padding: "22px 16px", textAlign: "center" }}><div style={{ fontSize: 15, fontWeight: 800, color: T.ink, fontFamily: T.fontDisplay }}>{q ? "Nobody matches" : kind === "saved" ? "No saved names yet" : "No contacts yet"}</div><div style={{ fontSize: 12.5, color: T.inkSoft, marginTop: 4, lineHeight: 1.45 }}>{q ? "Try another name, or dial the full GLOOBAL ID with +." : kind === "saved" ? "Open someone and tap Save name: the name you choose shows here and in your chats." : "People you pay on GLOOBAL, or chat with here, appear by themselves. Tap + to add someone."}</div></HellooCard> : <HellooCard>{shown.map((p, i) => { const open = openRow === p.id; const act = (Icon, label, fn, color) => <button onClick={() => fn && fn(p)} aria-label={label} title={label} className="v2-tap" style={{ width: 46, height: 46, borderRadius: "50%", border: "none", background: color, color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", boxShadow: `0 6px 14px ${color}55`, flexShrink: 0 }}><Icon size={20} /></button>; return <div key={p.id} style={{ borderTop: i ? `1px solid ${T.line}` : "none", background: open ? T.surfaceAlt : "transparent", transition: "background 0.2s" }}><button onClick={() => setOpenRow(p.id)} data-testid="helloo-contact-row" className="v2-tap" style={{ width: "100%", display: "flex", alignItems: "center", gap: 12, padding: "11px 14px", border: "none", background: "none", cursor: "pointer", textAlign: "left", fontFamily: T.fontBody }}><HellooAvatar person={p} size={46} online={p.online} flag={false} /><span style={{ flex: 1, minWidth: 0 }}><HellooVerifiedName person={p} size={15} />{p.accountName ? <span data-testid="helloo-contact-account-name" style={{ display: "block", fontSize: 11.5, color: T.inkFaint, fontWeight: 700, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", marginTop: 1 }}>On GLOOBAL: {p.accountName}</span> : null}</span><HlChevron size={16} color={T.inkFaint} /></button></div>; })}</HellooCard>}</div>{cardOf ? <HellooContactCard p={cardOf} onClose={() => setOpenRow(null)} onMessage={onMessage} onCall={onCall} onVideo={onVideo} onOpen={onOpen} onSaveName={onSaveName} onSaveToggle={onSaveToggle} onRemove={onRemove} /> : null}</HellooScreen>;
}

// One contact, on its own card: who they are (your name for them, their
// GLOOBAL name), where, their GLOOBAL ID, the last payment between you,
// then Message · Call · Video, and Save name · Full profile · Remove.
function HellooContactCard({ p, onClose, onMessage, onCall, onVideo, onOpen, onSaveName, onSaveToggle, onRemove }) {
  const go = (fn) => () => { onClose(); if (fn) fn(p); };
  return <HellooSheet label={p.name || "Contact"} onClose={onClose}><div data-testid="helloo-contact-card">
    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", textAlign: "center", padding: "4px 6px 14px" }}>
      <HellooAvatar person={p} size={84} online={p.online} flag={false} />
      <div style={{ marginTop: 10, display: "flex", justifyContent: "center", maxWidth: "100%" }}><HellooVerifiedName person={p} size={20} /></div>
      {p.accountName ? <div data-testid="helloo-contact-card-account" style={{ fontSize: 12.5, color: T.inkSoft, fontWeight: 700, marginTop: 3 }}>On GLOOBAL: {p.accountName}</div> : null}
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 8, fontSize: 12.5, fontWeight: 800, color: T.inkSoft }}><FlagEmoji flag={p.flag} size={16} shape="circle" border="none" />{p.country}{p.online ? <span style={{ color: HT.free }}>· Online</span> : null}</div>
      <div style={{ marginTop: 10, padding: "6px 12px", borderRadius: 12, background: T.surfaceAlt, fontSize: 13.5, fontWeight: 800 }}><ColoredGloobalId id={p.gloobalId || ""} /></div>
      {p.lastPaid ? <div style={{ fontSize: 12, fontWeight: 700, color: T.inkFaint, marginTop: 8 }}>{p.lastPaid}</div> : null}
    </div>
    <div style={{ display: "flex", gap: 8 }}>{[[HlChat, "Message", onMessage, T.accent], [HlPhone, "Call", onCall, HT.free], [HlVideo, "Video", onVideo, "#DB2777"]].map(([I, l, fn, c]) => <button key={l} onClick={go(fn)} aria-label={l} data-testid={`helloo-contact-card-${l.toLowerCase()}`} className="v2-tap" style={{ flex: 1, height: 64, borderRadius: 18, border: "none", background: c + "14", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 5, cursor: "pointer", fontFamily: T.fontBody }}><I size={21} color={c} /><span style={{ fontSize: 12, fontWeight: 800, color: T.ink }}>{l}</span></button>)}</div>
    <HellooCard style={{ marginTop: 12 }}>
      {onSaveToggle ? <span data-testid="helloo-contact-card-save" data-saved={p.saved ? "yes" : "no"} style={{ display: "block" }}><HellooToggleRow Icon={HlUserPlus} title="Saved contact" note="On all your profiles" on={Boolean(p.saved)} onChange={() => onSaveToggle(p)} color={HT.free} first testid="helloo-contact-save-switch" /></span> : null}
      {onSaveName ? <HellooRow Icon={HlPencil} title={p.accountName ? "Edit name" : "Save name"} value={p.accountName ? p.name : "Only you see it"} first={!onSaveToggle} onPress={go(onSaveName)} /> : null}
      <HellooRow Icon={HlUser} title="Full profile" first={!onSaveName && !onSaveToggle} onPress={go(onOpen)} />
      {onRemove ? <HellooRow Icon={HlTrash} title="Remove from contacts" danger color={T.negative} onPress={go(onRemove)} /> : null}
    </HellooCard>
  </div></HellooSheet>;
}

// The main colour of a picture: drawn tiny and averaged, with greys, near
// whites and near blacks left out, so a logo on white still gives its own
// colour. null until known, or when the picture has no colour to give.
function useHellooPictureColour(src) {
  const [col, setCol] = useStateH13(null);
  useEffectH13(() => {
    if (!src) { setCol(null); return undefined; }
    let gone = false;
    const img = new Image();
    img.onload = () => {
      try {
        const cv = document.createElement("canvas"); cv.width = 24; cv.height = 24;
        const ctx = cv.getContext("2d", { willReadFrequently: true }); ctx.drawImage(img, 0, 0, 24, 24);
        const d = ctx.getImageData(0, 0, 24, 24).data;
        let r = 0, g = 0, b = 0, n = 0;
        for (let i = 0; i < d.length; i += 4) { const R = d[i], G = d[i + 1], B = d[i + 2]; const mx = Math.max(R, G, B), mn = Math.min(R, G, B); if (d[i + 3] < 128 || mx - mn < 28 || mx > 245 || mx < 25) continue; r += R; g += G; b += B; n += 1; }
        if (!gone) setCol(n ? hellooReadable([r / n, g / n, b / n]) : null);
      } catch (e) { if (!gone) setCol(null); }
    };
    img.onerror = () => { if (!gone) setCol(null); };
    img.src = src;
    return () => { gone = true; };
  }, [src]);
  return col;
}
// White text has to read on it: a colour too light is deepened until it does.
function hellooReadable(c) {
  const lum = (x) => 0.2126 * x[0] + 0.7152 * x[1] + 0.0722 * x[2];
  let k = 1; while (lum(c.map((v) => v * k)) > 120 && k > 0.35) k -= 0.05;
  return c.map((v) => Math.round(v * k));
}
function hellooRgb(c, k = 1, a = 1) { return `rgba(${Math.round(Math.min(255, c[0] * k))}, ${Math.round(Math.min(255, c[1] * k))}, ${Math.round(Math.min(255, c[2] * k))}, ${a})`; }
function hellooHexRgb(hex) {
  const m = /^#?([0-9a-f]{6})$/i.exec(String(hex || "").trim());
  if (!m) return null;
  const n = parseInt(m[1], 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

// The shop's colours from the theme in use (its creator half), for a shop
// whose logo gives no colour of its own.
function hellooShopColors() {
  try {
    const k = (hellooSavedTheme() || "").replace(/^g-/, "");
    const g = (typeof GLOOBAL_THEMES === "object" && (GLOOBAL_THEMES[k] || GLOOBAL_THEMES.peacock)) || null;
    if (g && g.creator) return g.creator;
  } catch (e) { /* fall through */ }
  return { accent: "#0B7A55" };
}
